
        function addSpeculationRules() {
            if (HTMLScriptElement.supports && HTMLScriptElement.supports('speculationrules')) {
                const script = document.createElement('script');
                script.type = 'speculationrules';
                script.textContent = JSON.stringify(
					    {
					      "prerender": [
					        {
							  "source": "document",
					          "where": { "href_matches": "/" },
					          "eagerness": "moderate"
					        },
					        {
							  "source": "document",
					          "where": { "href_matches": "/all-fooding-wayanad.html" },
					          "eagerness": "conservative"
					        },
					        {
							  "source": "document",
					          "where": { "href_matches": "/all-locations-wayanad.html" },
					          "eagerness": "conservative"
					        },
					        {
							  "source": "document",
					          "where": { "href_matches": "/bwstays-booking.html" },
					          "eagerness": "conservative"
					        }
					      ],
					      "prefetch": [
					        {
						 	  "source": "document",
					          "where": { "href_matches": ["/bw*.html" ]},
					          "eagerness": "conservative"
					        },
						    {
						  	  "source": "document",
							  "where": {
								"and": [
								  { "href_matches": "/apiblogs*" } 
								]
						     },
						     "eagerness": "conservative"
						    }
					      ],
						  "cache_control": {
							"max_age": 300,
							"stale_while_revalidate": 86400
						  },
						  "network_conditions": {
							"connection_types": ["wifi", "4g"],
							"save_data": false
						  },
						  "device_conditions": {
							"memory": {
							  "min": 1024
							},
							"storage": {
							  "available_mb": 50
							}
						  }
    				}
					);
                document.head.appendChild(script);
            } else {
            }
        }
        function addHoverBasedRules() {
            if (HTMLScriptElement.supports && HTMLScriptElement.supports('speculationrules')) {
                const hoverScript = document.createElement('script');
                hoverScript.type = 'speculationrules';
                hoverScript.textContent = JSON.stringify({
                    "prerender": [
                        {
                            "where": { "href_matches": "/*.html" },
                            "eagerness": "conservative"
                        }
                    ]
                });
                document.head.appendChild(hoverScript);
            }
        }